const UI={lang:'ar',dashboard:null,roles:[],providerStatus:null,restoreFocus:null,projectPlan:null,projectRunning:false,didAutoResume:false};
const $=(s)=>document.querySelector(s);const $$=(s)=>[...document.querySelectorAll(s)];
function tr(key){return COPY[UI.lang][key]??COPY.ar[key]??key}
function escapeHTML(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function loadData(){const [health,registry,tasks,approvalResponse,providerStatus,planResponse]=await Promise.all([fetch('http://127.0.0.1:8766/api/health').then(r=>{if(!r.ok)throw Error('local API unavailable');return r.json()}),fetch('http://127.0.0.1:8766/api/roles').then(r=>{if(!r.ok)throw Error('role registry unavailable');return r.json()}),fetch('http://127.0.0.1:8766/api/tasks').then(r=>{if(!r.ok)throw Error('task store unavailable');return r.json()}),fetch('http://127.0.0.1:8766/api/approvals').then(r=>{if(!r.ok)throw Error('approval store unavailable');return r.json()}),fetch('http://127.0.0.1:8766/api/provider-status').then(r=>r.ok?r.json():null).catch(()=>null),fetch('http://127.0.0.1:8766/api/project-plan').then(r=>r.ok?r.json():null).catch(()=>null)]);UI.health=health;UI.providerStatus=providerStatus;UI.readiness=registry;UI.roles=registry.roles;UI.projectPlan=planResponse?.plan||null;if(UI.projectPlan){$('#project-name').value=UI.projectPlan.name;$('#project-goal').value=UI.projectPlan.goal}UI.dashboard={data_as_of:new Date().toISOString(),approvals:approvalResponse.approvals,tasks:tasks.tasks.map(t=>{const role=registry.roles.find(r=>r.role_id===t.role_id);const elapsed=t.completed_at?Math.max(0,new Date(t.completed_at)-new Date(t.created_at)):null;return {...t,name_ar:role?.name_ar||t.role_id,name_en:role?.name_en||t.role_id,runtime_display:elapsed===null?'—':`${(elapsed/1000).toFixed(1)} s`,result:t.result||{output:t.error||''}}})};document.querySelector('#task-count').textContent=UI.dashboard.tasks.length;render();populateTaskRoles();renderAgentReadiness();renderProjectPlan();$('#refresh-data').dataset.updated='true';announce(`${tr('liveLocal')}: ${UI.dashboard.tasks.length}`);if(!UI.didAutoResume){UI.didAutoResume=true;if(['approved','running'].includes(UI.projectPlan?.status))setTimeout(()=>runProjectPlan(),0)}}
function announce(message){let el=$('#announcer');if(!el){el=document.createElement('div');el.id='announcer';el.className='sr-only';el.setAttribute('role','status');el.setAttribute('aria-live','polite');document.body.append(el)}el.textContent=message}
function setLanguage(lang){UI.lang=lang;document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';$$('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;el.textContent=tr(key)});$$('[data-placeholder-ar]').forEach(el=>el.placeholder=el.dataset[`placeholder${lang==='ar'?'Ar':'En'}`]);$$('[data-i18n-title-ar]').forEach(el=>el.title=el.dataset[`i18nTitle${lang==='ar'?'Ar':'En'}`]);$('#lang-toggle').textContent=lang==='ar'?'English':'العربية';$('#lang-toggle').setAttribute('aria-label',lang==='ar'?'Switch to English':'التبديل إلى العربية');if(UI.dashboard)render();if(UI.projectPlan)renderProjectPlan();renderAgentReadiness();}
function statusPill(status){let cls=['completed','approved'].includes(status)?'success':['queued','running','waiting_approval','cancel_requested','revision_required'].includes(status)?'warning':['failed','rejected','blocked','cancelled'].includes(status)?'danger':'neutral';return `<span class="pill ${cls}">${escapeHTML(COPY[UI.lang].stateNames[status]||COPY[UI.lang][status]||status)}</span>`}
function renderTasks(){const query=$('#task-search').value.trim().toLocaleLowerCase();const filter=$('#status-filter').value;const allStatuses=['queued','running','waiting_approval','completed','approved','rejected','cancelled','failed','blocked'];const current=filter;$('#status-filter').innerHTML=`<option value="all">${escapeHTML(tr('allStatuses'))}</option>`+allStatuses.map(s=>`<option value="${s}">${escapeHTML(COPY[UI.lang].stateNames[s]||s)}</option>`).join('');$('#status-filter').value=[...$('#status-filter').options].some(o=>o.value===current)?current:'all';const tasks=(UI.dashboard?.tasks||[]).filter(t=>(filter==='all'||t.status===filter)&&(!query||[t.task_id,t.trace_id,t.name_ar,t.name_en,t.role_id].join(' ').toLocaleLowerCase().includes(query)));$('#operations-body').innerHTML=tasks.map((t,i)=>{const r=UI.roles.find(x=>x.role_id===t.role_id);return `<tr><td><span class="task-name">${escapeHTML(t.input.slice(0,90))}</span><small class="task-meta">${escapeHTML(t.task_id)}</small></td><td>${escapeHTML(r?UI.lang==='ar'?r.name_ar:r.name_en:t.role_id)}</td><td>${statusPill(t.status)}${t.cancel_requested?`<small>${escapeHTML(tr('cancelRequested'))}</small>`:''}</td><td class="duration">${escapeHTML(t.runtime_display)}</td><td><button class="trace-link" data-task-index="${i}" type="button" aria-label="${UI.lang==='ar'?'تفاصيل التتبع':'Open trace details'} ${escapeHTML(t.trace_id)}">${escapeHTML(t.trace_id)}</button></td></tr>`}).join('');$('#empty-state').hidden=tasks.length>0;$('#empty-state').textContent=tasks.length?tr('noResults'):tr('noTasksYet');$$('[data-task-index]').forEach(btn=>btn.addEventListener('click',()=>openTask(tasks[Number(btn.dataset.taskIndex)],btn)));$('#metric-total').textContent=UI.dashboard?.tasks.length||0;$('#metric-completed').textContent=UI.dashboard?.tasks.filter(t=>['completed','approved'].includes(t.status)).length||0;$('#metric-failed').textContent=UI.dashboard?.tasks.filter(t=>['failed','rejected','blocked'].includes(t.status)).length||0;renderInbox();renderApprovals()}
function populateTaskRoles(){const select=$('#new-task-role');const chosen=select.value||'D-00';select.innerHTML=UI.roles.map(r=>`<option value="${escapeHTML(r.role_id)}">${escapeHTML(r.role_id)} · ${escapeHTML(UI.lang==='ar'?r.name_ar:r.name_en)}</option>`).join('');if(UI.roles.some(r=>r.role_id===chosen))select.value=chosen;}
const PROJECT_COPY={ar:{projectRoom:'غرفة المشروع',directorRule:'مدير البرنامج · تخطيط قائم على قواعد',projectIntro:'اكتبي الهدف، راجعي توزيع الأدوار المقترح، ثم ابدئي التنفيذ المحلي. التخطيط لا يستدعي نموذجًا ولا يشغّل المهام تلقائيًا.',projectName:'اسم المشروع',projectGoal:'الهدف أو الطلب',makePlan:'اقترح خطة',startProject:'نفّذ الخطوة التالية محليًا',planEmpty:'ستظهر الخطة هنا بعد إدخال الهدف.',planTitle:'خطة مقترحة',planBasis:'اقتراح آلي بقواعد محلية؛ راجعيه وعدّليه قبل التشغيل.',director:'مدير البرنامج',planTask:'المخرج المتوقع',runConfirm:'سيُرسل الدور التالي كمهمة محلية إلى Ollama عبر API الموجود. ابدئي هذه الخطوة؟',running:'تشغيل الخطوة محليًا…',nextStep:'اكتملت الخطوة؛ راجعي نتيجتها ثم تابعي للخطوة التالية.',done:'اكتملت كل خطوات الخطة.',failed:'تعذرت هذه الخطوة:',noMatch:'لم أجد أدوارًا مناسبة في السجل لهذا النوع؛ أضيفي دورًا يدويًا من اختيارك.',unknown:'حالة الدور غير متحققة',tasks:'خطوات الخطة',saved:'تم حفظ الخطة في هذا المتصفح فقط.',fullPlanTitle:'خطة تطوير Wejdan Life OS',fullPlanIntro:'خطة المشروع كاملة موزعة على الفرق الـ11. كل بطاقة تعرض هدف الفريق وأعماله وتسليماته واعتمادياته وأدوار المراجعة.',teamGoal:'هدف الفريق',teamWork:'نطاق العمل',teamOutput:'المخرجات المتوقعة',teamGate:'بوابة المراجعة',teamDependency:'يعتمد على',teamRoles:'أدوار الفريق',directorGate:'مدير البرنامج',qaGate:'مراجع الجودة',startProject:'انقلي هذه المرحلة إلى غرفة المشروع لمراجعة تكليفاتها.'},en:{projectRoom:'Project room',directorRule:'Program Director · rule-based planning',projectIntro:'Describe the goal, review the suggested role assignments, then start local execution. Planning makes no model call and never dispatches automatically.',projectName:'Project name',projectGoal:'Goal or request',makePlan:'Suggest a plan',startProject:'Run next local step',planEmpty:'Your plan will appear here after you enter a goal.',planTitle:'Proposed plan',planBasis:'Local rule-based suggestion; review and edit it before running.',director:'Program Director',planTask:'Expected output',runConfirm:'The next role will be submitted as a local Ollama task through the existing API. Start this step?',running:'Running this local step…',nextStep:'Step completed; review its result before continuing.',done:'All plan steps are complete.',failed:'This step could not complete:',noMatch:'No matching roles found in the registry; choose roles manually.',unknown:'Role state is unverified',tasks:'Plan steps',saved:'Plan is saved in this browser only.',fullPlanTitle:'Wejdan Life OS development plan',fullPlanIntro:'The full project plan across all 11 teams. Each card includes the goal, scope, deliverables, dependencies, and review roles.',teamGoal:'Team goal',teamWork:'Scope',teamOutput:'Expected deliverables',teamGate:'Review gate',teamDependency:'Depends on',teamRoles:'Team roles',directorGate:'Program Director',qaGate:'Quality reviewer'}};
function pc(key){return PROJECT_COPY[UI.lang][key]||PROJECT_COPY.ar[key]||COPY[UI.lang]?.[key]||COPY.ar?.[key]||key}
function selectPlanRoles(goal){const text=goal.toLocaleLowerCase(),groups=[];const add=(team,terms)=>{if(terms.some(term=>text.includes(term))&&!groups.includes(team))groups.push(team)};add('PROD',['ميزة','منتج','feature','product','requirement','متطلب','تطوير']);add('UR',['مستخدم','بحث','مقابلة','user','research','interview']);add('DES',['تصميم','واجهة','تجربة','رحلة','design','ux','ui']);add('FE',['واجهة','تطبيق','شاشة','ويب','frontend','mobile','screen']);add('BE',['قاعدة','api','بيانات','خلفية','backend','database']);add('AI',['ذكاء','إيجنت','وكيل','نموذج','agent','ai','model']);add('SEC',['أمان','خصوصية','حماية','security','privacy']);if(!groups.length)groups.push('PROD','FE');const selectors={PROD:['product lead','قائد المنتج'],UR:['user research lead','قائد أبحاث المستخدمين'],DES:['ux and product design lead','قائد تجربة المستخدم'],FE:['frontend engineering lead','قائد هندسة الواجهات'],BE:['backend engineering lead','قائد هندسة الأنظمة الخلفية'],AI:['ai engineering lead','قائد هندسة الذكاء'],SEC:['security lead','قائد الأمن']};const steps=[];for(const [team,words]of groups.map(team=>[team,selectors[team]||[]])){const role=UI.roles.find(r=>r.team_id===team&&words.some(w=>`${r.name_en} ${r.name_ar}`.toLocaleLowerCase().includes(w)))||UI.roles.find(r=>r.team_id===team&&r.reviewer_roles?.includes('QA-01'));if(role&&!steps.some(s=>s.role_id===role.role_id))steps.push(role)}return [UI.roles.find(r=>r.role_id==='D-00'),UI.roles.find(r=>r.role_id==='PMO-01'),...steps].filter((r,i,a)=>r&&a.findIndex(x=>x.role_id===r.role_id)===i)}
async function proposeProjectPlan(){const name=$('#project-name').value.trim(),goal=$('#project-goal').value.trim();if(!name||!goal){$('#project-name').reportValidity();return}const button=$('#plan-project');button.disabled=true;$('#project-status').textContent=UI.lang==='ar'?'جارٍ تجهيز المسودة…':'Preparing the draft…';try{const roles=selectPlanRoles(goal);const steps=roles.map((role,index)=>({role_id:role.role_id,reviewer_role_id:'QA-01',title:UI.lang==='ar'?role.name_ar:role.name_en,task:index===0?'إعداد موجز المبادرة: النطاق، معايير القبول، المخاطر والتبعيات.':index===1?'تنظيم تسلسل التنفيذ، مالك كل خطوة، والعوائق وحدود العمل الجاري.':`تقديم مخرج ${role.expected_outputs} بما يخدم الهدف المحدد.`,acceptance:index===0?'موجز يحدد النطاق ومعايير القبول والمخاطر والتبعيات، مع تمييز الافتراضات عن الأدلة.':index===1?'تسلسل واضح بخطوة واحدة جارية كحد أقصى، مع مالك وعائق واعتمادية لكل مهمة.':String(role.expected_outputs||'مخرج يطابق الهدف').slice(0,1400)}));const response=await fetch('http://127.0.0.1:8766/api/project-plan',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name,goal,steps,risks:['التوزيع مسودة أولية ويحتاج مراجعة المالكة قبل التشغيل.','الحالة والنتيجة تستندان إلى أدلة SQLite المحلية؛ غياب الدليل يبقى غير مؤكد.']})});const data=await response.json();if(!response.ok)throw Error(data.detail||data.error||'PLAN_CREATE_FAILED');UI.projectPlan=data.plan;$('#project-status').textContent=pc('planSaved');renderProjectPlan();announce(pc('planSaved'))}catch(error){$('#project-status').textContent=`${pc('failed')} ${error.message}`;announce($('#project-status').textContent)}finally{button.disabled=false}}
function renderProjectPlan(){const plan=UI.projectPlan;const approve=$('#approve-project'),run=$('#run-project');if(!plan){approve.hidden=true;run.hidden=true;$('#project-stage').textContent=pc('noPlan');return}approve.hidden=plan.status!=='draft';run.hidden=!['approved','running'].includes(plan.status);approve.disabled=UI.projectRunning;run.disabled=UI.projectRunning||plan.status==='blocked'||plan.status==='completed';const labels={draft:pc('draftStatus'),approved:pc('approvedStatus'),running:pc('runningStatus'),blocked:pc('blockedStatus'),completed:pc('completedStatus')};const done=plan.steps.filter(s=>s.status==='completed').length;$('#project-stage').innerHTML=`<strong>${escapeHTML(plan.name)}</strong><span>${escapeHTML(labels[plan.status]||plan.status)} · ${done}/${plan.steps.length}</span>`;const rows=plan.steps.map(step=>{const role=UI.roles.find(r=>r.role_id===step.role_id);const title=role?(UI.lang==='ar'?role.name_ar:role.name_en):step.role_id;const mark=step.status==='completed'?'✓':step.status==='running'||step.status==='queued'?'…':step.status==='blocked'?'!':'○';const pillState=step.status==='completed'?'completed':step.status==='blocked'?'failed':step.status==='running'?'running':step.status==='queued'?'queued':step.status==='revision_required'?'revision_required':step.status==='planned'?'planned':'blocked';const reviewer=UI.roles.find(r=>r.role_id===step.reviewer_role_id);const reviewerName=reviewer?(UI.lang==='ar'?reviewer.name_ar:reviewer.name_en):step.reviewer_role_id||'QA-01';return `<article class="project-step"><span class="project-step-mark" aria-hidden="true">${mark}</span><div><strong>${escapeHTML(title)}</strong><small>${escapeHTML(step.role_id)} · ${escapeHTML(role?.readiness?.registry_state||'UNKNOWN')} · ${escapeHTML(pc('stepReviewer'))}: ${escapeHTML(reviewerName)}</small><p>${escapeHTML(step.task||plan.goal)}</p><p><b>${escapeHTML(pc('stepAcceptance'))}:</b> ${escapeHTML(step.acceptance||'—')}</p>${step.depends_on?.length?`<small>${escapeHTML(pc('stepDependency'))}: ${escapeHTML(step.depends_on.join('، '))}</small>`:''}${step.review_verdict?`<small>${escapeHTML(pc('reviewVerdict'))}: ${escapeHTML(step.review_verdict)}</small>`:''}${step.revision_count?`<small>${escapeHTML(pc('revisionCount'))}: ${step.revision_count}/1</small>`:''}${step.block_reason?`<p class="plan-block-reason">${escapeHTML(step.block_reason)}</p>`:''}${step.output?`<details><summary>${escapeHTML(pc('planTask'))}</summary><pre>${escapeHTML(step.output)}</pre></details>`:''}${step.trace_id?`<small dir="ltr">${escapeHTML(step.trace_id)}</small>`:''}</div>${statusPill(pillState)}</article>`}).join('');$('#project-plan').innerHTML=`<div class="project-plan-heading"><h3>${escapeHTML(pc('projectPlanTitle'))}: ${escapeHTML(plan.name)}</h3><span>${escapeHTML(labels[plan.status]||plan.status)}</span></div><p class="catalog-note">${escapeHTML(pc('planDraftNote'))} ${escapeHTML(pc('planSaved'))}</p><div class="project-steps">${rows}</div>`}
async function approveProjectPlan(){const plan=UI.projectPlan;if(!plan||plan.status!=='draft')return;if(!window.confirm(pc('approveConfirm')))return;const response=await fetch(`http://127.0.0.1:8766/api/project-plan/${encodeURIComponent(plan.plan_id)}/approve`,{method:'POST'});const data=await response.json();if(!response.ok){$('#project-status').textContent=`${pc('failed')} ${data.error||'APPROVAL_FAILED'}`;return}UI.projectPlan=data.plan;$('#project-status').textContent=pc('planApproved');renderProjectPlan();await runProjectPlan()}
async function runProjectPlan(){const plan=UI.projectPlan;if(!plan||UI.projectRunning||!['approved','running'].includes(plan.status))return;UI.projectRunning=true;$('#project-status').textContent=pc('planRunning');renderProjectPlan();try{for(let count=0;count<24;count++){let snapshot=await fetch('http://127.0.0.1:8766/api/project-plan').then(r=>r.json());UI.projectPlan=snapshot.plan;if(!snapshot.plan||['blocked','completed'].includes(snapshot.plan.status))break;const step=snapshot.plan.steps.find(s=>s.status!=='completed');if(!step)break;if(['queued','running'].includes(step.status)&&step.task_id){await pollTask(step.task_id)}else{const response=await fetch(`http://127.0.0.1:8766/api/project-plan/${encodeURIComponent(snapshot.plan.plan_id)}/dispatch`,{method:'POST'});const data=await response.json();if(!response.ok)throw Error(data.error||'DISPATCH_FAILED');await pollTask(data.task_id)}snapshot=await fetch('http://127.0.0.1:8766/api/project-plan').then(r=>r.json());UI.projectPlan=snapshot.plan;if(snapshot.plan?.status==='blocked')break;if(snapshot.plan?.status==='completed')break}const final=await fetch('http://127.0.0.1:8766/api/project-plan').then(r=>r.json());UI.projectPlan=final.plan;$('#project-status').textContent=final.plan?.status==='completed'?pc('planComplete'):final.plan?.status==='blocked'?`${pc('planBlocked')} ${final.plan.steps.find(s=>s.status==='blocked')?.block_reason||''}`:pc('planRunning');announce($('#project-status').textContent)}catch(error){$('#project-status').textContent=`${pc('failed')} ${error.message}`;announce($('#project-status').textContent)}finally{UI.projectRunning=false;renderProjectPlan();await loadData().catch(()=>{})}}
async function renderAgentReadiness(){const host=$('#agent-readiness');if(!host)return;const registry=UI.readiness;const important=['D-00','PMO-01','QA-01'];const active=UI.roles.filter(role=>(role.active_task_count||0)>0);const selected=[...new Set([...active.map(r=>r.role_id),...important])].map(id=>UI.roles.find(r=>r.role_id===id)).filter(Boolean).slice(0,8);const labels={contract:pc('contractStatus'),readiness:pc('readinessStatus'),activity:pc('activityStatus')};const date=registry?.readiness_generated_at||registry?.generated_at||'—';$('#readiness-stamp').textContent=`${pc('lastUpdated')}: ${date}`;$('#agent-source').textContent=registry?.source||pc('agentSource');host.innerHTML=selected.map(role=>{const evidence=role.readiness||{};const readiness=evidence.specialist_artifact==='PASS'&&evidence.review==='PASS'?pc('readyEvidence'):evidence.registry_state==='MOCK_TESTED'?pc('roleDefined'):pc('unknownReadiness');const activity=role.current_activity==='RUNNING'?`${pc('activeNow')} · ${role.active_task_count}`:pc('notActive');const contract=role.contract_status==='REGISTERED'?`${pc('roleDefined')} · ${role.contract_id||role.role_id}`:pc('unknownReadiness');const expert=evidence.human_expert_approved?pc('humanApproved'):pc('noExpertApproval');return `<article class="agent-readiness-card"><h3>${escapeHTML(UI.lang==='ar'?role.name_ar:role.name_en)}</h3><small dir="ltr">${escapeHTML(role.role_id)}</small><dl><div><dt>${escapeHTML(labels.contract)}</dt><dd>${escapeHTML(contract)}</dd></div><div><dt>${escapeHTML(labels.readiness)}</dt><dd>${escapeHTML(readiness)}</dd><small>${escapeHTML(evidence.specialist_artifact||'UNKNOWN')} / ${escapeHTML(evidence.review||'UNKNOWN')} · ${escapeHTML(expert)}</small></div><div><dt>${escapeHTML(labels.activity)}</dt><dd>${escapeHTML(activity)}</dd></div></dl></article>`}).join('')||`<p class="empty-state">${escapeHTML(pc('unknownReadiness'))}</p>`}
function teamKey(role){return role.team_id==='D'?'D':role.team_id}
function renderRoles(){const teamSelect=$('#team-filter');const current=teamSelect.value;const groups=[...new Map(UI.roles.map(r=>[teamKey(r),r.team_name])).entries()].sort((a,b)=>a[0].localeCompare(b[0]));teamSelect.innerHTML=`<option value="all">${tr('allTeams')}</option>`+groups.map(([id])=>`<option value="${escapeHTML(id)}">${escapeHTML(COPY[UI.lang].teamNames[id]||id)}</option>`).join('');if([...teamSelect.options].some(o=>o.value===current))teamSelect.value=current;const q=$('#role-search').value.toLocaleLowerCase();const team=teamSelect.value;const state=$('#role-status-filter').value;const roles=UI.roles.filter(r=>(team==='all'||teamKey(r)===team)&&(state==='all'||(state==='mock'?r.activation_state==='MOCK_TESTED':r.activation_state==='SPECIFIED'))&&(!q||`${r.name_ar} ${r.name_en} ${r.role_id} ${r.team_name}`.toLocaleLowerCase().includes(q)));$('#role-list').innerHTML=roles.map(r=>`<article class="role-card"><strong lang="ar" dir="rtl" title="${escapeHTML(r.name_ar)}">${escapeHTML(r.name_ar)}</strong><small class="role-en" lang="en" dir="ltr">${escapeHTML(r.name_en)}</small><small>${escapeHTML(COPY[UI.lang].teamNames[teamKey(r)]||r.team_name)} · ${escapeHTML(r.role_id)}</small><span class="role-badge ${r.activation_state==='MOCK_TESTED'?'mock':''}">${r.activation_state==='MOCK_TESTED'?tr('roleState.mock'):tr('roleState.specified')}</span></article>`).join('');$('#role-empty').hidden=roles.length>0;$('#role-results-count').textContent=UI.lang==='ar'?`عدد الأدوار المطابقة: ${roles.length}`:`Matching roles: ${roles.length}`;}
function renderInbox(){const tasks=(UI.dashboard?.tasks||[]).filter(t=>['queued','running','waiting_approval','blocked','cancelled'].includes(t.status));$('#inbox-count').textContent=tasks.length;$('#inbox-list').innerHTML=tasks.length?tasks.slice(0,20).map(t=>`<article class="inbox-item"><span class="inbox-symbol lilac-text" aria-hidden="true">◌</span><div><strong>${escapeHTML(t.input.slice(0,90))}</strong><small dir="ltr">${escapeHTML(t.trace_id)}</small></div>${statusPill(t.status)}</article>`).join(''):`<p>${escapeHTML(tr('noWaitingTasks'))}</p>`}
function renderApprovals(){const approvals=(UI.dashboard?.approvals||[]).filter(a=>a.status==='pending');$('#approval-count').textContent=approvals.length;$('#approval-list').innerHTML=approvals.length?approvals.map(a=>`<article class="approval-item"><strong>${escapeHTML(a.task_id)}</strong><small dir="ltr">${escapeHTML(a.trace_id)}</small><p>${escapeHTML(a.proposal.slice(0,500))}</p><div class="task-action-row"><button class="button primary" data-approval-decision="approved" data-approval-id="${escapeHTML(a.approval_id)}">${escapeHTML(tr('approveLocal'))}</button><button class="button quiet" data-approval-decision="rejected" data-approval-id="${escapeHTML(a.approval_id)}">${escapeHTML(tr('rejectLocal'))}</button></div></article>`).join(''):`<p>${escapeHTML(tr('noApprovals'))}</p>`;$$('[data-approval-id]').forEach(btn=>btn.addEventListener('click',()=>decideApproval(btn.dataset.approvalId,btn.dataset.approvalDecision)))}
async function decideApproval(id,decision){const message=decision==='approved'?tr('confirmApprove'):tr('confirmReject');if(!window.confirm(message))return;const response=await fetch(`http://127.0.0.1:8766/api/approvals/${encodeURIComponent(id)}/decision`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({decision,note:tr('ownerDecisionNote')})});if(!response.ok){announce(tr('apiUnavailable'));return}await loadData()}
function render(){renderTasks();renderRoles();populateTaskRoles();if(UI.health){const status=UI.health.status==='ok'?'success':'warning';$('.status-panel .panel-heading .pill').textContent=UI.lang==='ar'?(status==='success'?'الخدمات متصلة':'تحتاج فحصًا'):(status==='success'?'Services online':'Check required');$('.status-panel .panel-heading .pill').className=`pill ${status}`;const rows=$$('.status-panel .health-row');if(rows[0]){rows[0].querySelector('strong').textContent='n8n local';rows[0].querySelector('small').textContent=UI.health.n8n_webhook||'127.0.0.1';rows[0].querySelector('.health-state').textContent=UI.health.n8n_ready?(UI.lang==='ar'?'متصل الآن':'Online now'):(UI.lang==='ar'?'غير متصل':'Offline');rows[0].querySelector('.health-state').className=`health-state ${UI.health.n8n_ready?'good':'muted'}`}$('#model-name').textContent=`Ollama · ${UI.health.model||'local model'}`;$('#model-detail').textContent=UI.lang==='ar'?'استدلال محلي عبر n8n':'Local inference via n8n';$('#model-state').textContent=UI.health.ollama_ready?(UI.lang==='ar'?'جاهز محليًا':'Ready locally'):(UI.lang==='ar'?'غير متصل':'Offline');$('#model-state').className=`health-state ${UI.health.ollama_ready?'good':'muted'}`;if(rows[2]){rows[2].querySelector('small').textContent=UI.lang==='ar'?'مهام محفوظة في SQLite محليًا':'Tasks persisted in local SQLite';rows[2].querySelector('.health-state').textContent=UI.lang==='ar'?'محلي':'Local'}}const codexState=UI.providerStatus?.states?.find(x=>x.state_key==='APP_CODEX_E2E_LIVE_VERIFIED');$('#codex-provider-evidence').textContent=UI.lang==='ar'?(codexState?.status==='NOT_VERIFIED'?'Codex: ربط التطبيق باستدعاء حي غير متحقق؛ تشغيل Ollama المحلي مستقل وجاهز.':'حالة ربط Codex غير متاحة.'):(codexState?.status==='NOT_VERIFIED'?'Codex app live call is not verified; local Ollama remains independently available.':'Codex integration status unavailable.');$('.data-stamp span:last-child').textContent=tr('liveLocal');}
async function openTask(task,button){UI.restoreFocus=button;try{const response=await fetch(`http://127.0.0.1:8766/api/tasks/${encodeURIComponent(task.task_id)}`);if(response.ok)task=await response.json()}catch{}const role=UI.roles.find(r=>r.role_id===task.role_id);const values=[[tr('taskName'),task.input],[tr('role'),role?(UI.lang==='ar'?role.name_ar:role.name_en):task.role_id],[UI.lang==='ar'?'معرّف المهمة':'Task ID',task.task_id],[UI.lang==='ar'?'معرّف التتبع':'Trace ID',task.trace_id],[tr('status'),COPY[UI.lang].stateNames[task.status]||task.status],[tr('attempt'),String(task.attempt||1)],[UI.lang==='ar'?'المزوّد':'Provider',task.provider||task.result?.provider||'ollama-local'],[UI.lang==='ar'?'النموذج':'Model',task.result?.model||'—'],[UI.lang==='ar'?'النتيجة':'Result',task.result?.output||task.error||'']];const rows=(task.steps||[]).map((step,i)=>[`${UI.lang==='ar'?'المرحلة':'Step'} ${i+1} · ${step.role_id} (${step.step_type})`,`${step.status}${step.n8n_execution_id?` · n8n #${step.n8n_execution_id}`:''}
${step.output||step.error||''}`]);if(task.result?.collaboration)rows.push([UI.lang==='ar'?'نتيجة المراجع':'Reviewer verdict',task.result.collaboration.review_output]);rows.push([UI.lang==='ar'?'عناصر الذاكرة المشتركة':'Shared memory entries',String((task.memory||[]).length)]);if(task.cancel_requested)rows.push([UI.lang==='ar'?'الإلغاء':'Cancellation',tr('cancelCheckpointNote')]);const controls=[];if(['queued','running'].includes(task.status))controls.push(`<button class="button quiet" id="task-cancel">${escapeHTML(tr('cancelTask'))}</button>`);if(['failed','cancelled'].includes(task.status))controls.push(`<button class="button primary" id="task-retry">${escapeHTML(tr('retryTask'))}</button>`);controls.push(`<button class="button quiet" id="task-export">${escapeHTML(tr('exportTask'))}</button>`);if(!['queued','running'].includes(task.status))controls.push(`<button class="button quiet" id="task-delete">${escapeHTML(tr('deleteTask'))}</button>`);$('#dialog-content').innerHTML=`<dl class="detail-list">${[...values,...rows].map(([k,v],i)=>`<dt>${escapeHTML(k)}</dt><dd ${i===2||i===3?'dir="ltr"':''}>${escapeHTML(v)}</dd>`).join('')}</dl><div class="task-action-row">${controls.join('')}</div><p class="detail-notice">${escapeHTML(task.requires_approval?tr('approvalRecordOnly'):task.provider==='codex-subscription'?tr('codexCostNotice'):tr('localCostNotice'))}</p>`;const dlg=$('#task-dialog');dlg.showModal();$('#dialog-title').focus();$('#task-cancel')?.addEventListener('click',()=>cancelTask(task.task_id));$('#task-retry')?.addEventListener('click',()=>retryTask(task.task_id));$('#task-export')?.addEventListener('click',()=>exportTask(task.task_id));$('#task-delete')?.addEventListener('click',()=>deleteTask(task.task_id));}
function closeDialog(){const d=$('#task-dialog');if(d.open)d.close();UI.restoreFocus?.focus();}
function exportSummary(){const d=UI.dashboard;const redacted={schema_version:'local-task-export.v1',data_as_of:d.data_as_of,provider:'mixed-local',tasks:d.tasks.map(({task_id,trace_id,role_id,status,runtime_display,result})=>({task_id,trace_id,role_id,status,runtime_display,model:result?.model||null,n8n_execution_id:result?.n8n_execution_id||null}))};const blob=new Blob([JSON.stringify(redacted,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='wejdan-local-task-summary.json';a.click();URL.revokeObjectURL(url);announce(UI.lang==='ar'?'تم تصدير ملخص المهام المحلي.':'Local task summary exported.')}
async function pollTask(taskId){for(let i=0;i<300;i++){const response=await fetch(`http://127.0.0.1:8766/api/tasks/${encodeURIComponent(taskId)}`);if(!response.ok)throw Error('Task status unavailable');const task=await response.json();if(['completed','approved','rejected','failed','cancelled','blocked','waiting_approval'].includes(task.status))return task;await new Promise(resolve=>setTimeout(resolve,800))}throw Error('Task is still running; refresh the task list to inspect it.')}
async function submitTask(event){event.preventDefault();const input=$('#new-task-input').value.trim();const role_id=$('#new-task-role').value;if(!input)return;const button=$('#submit-task'),status=$('#task-submit-status');button.disabled=true;status.classList.remove('sr-only');status.textContent=tr('taskRunning');try{const response=await fetch('http://127.0.0.1:8766/api/tasks',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({input,role_id,provider:$('#new-task-provider').value,collaborate:$('#task-collaborate').checked,reviewer_role_id:'QA-01',requires_approval:$('#task-requires-approval').checked,asynchronous:true})});const queued=await response.json();if(!response.ok)throw Error(queued.detail||queued.error||'Task failed');const result=await pollTask(queued.task_id);$('#new-task-input').value='';await loadData();status.textContent=result.status==='waiting_approval'?`${tr('awaitingApproval')} ${result.task_id}`:result.status==='completed'?`${tr('taskCompleted')} ${result.task_id} · ${result.trace_id}${result.collaboration?' · QA‑01 reviewed':''}`:`${tr('taskFailed')}: ${result.status}`;announce(status.textContent)}catch(error){status.textContent=`${tr('taskFailed')}: ${error.message}`;announce(status.textContent)}finally{button.disabled=false}}
async function cancelTask(taskId){const response=await fetch(`http://127.0.0.1:8766/api/tasks/${encodeURIComponent(taskId)}/cancel`,{method:'POST'});if(!response.ok){announce(tr('taskActionFailed'));return}await loadData();const info=await response.json();announce(info.inference_started===false?tr('cancelledBeforeRun'):tr('cancelCheckpointNote'))}
async function retryTask(taskId){const response=await fetch(`http://127.0.0.1:8766/api/tasks/${encodeURIComponent(taskId)}/retry`,{method:'POST'});const data=await response.json();if(!response.ok){announce(tr('taskActionFailed'));return}closeDialog();const result=await pollTask(data.task_id);await loadData();announce(`${tr('retryTask')}: ${result.status} · ${result.task_id}`)}
async function exportTask(taskId){const response=await fetch(`http://127.0.0.1:8766/api/tasks/${encodeURIComponent(taskId)}/export`);if(!response.ok){announce(tr('taskActionFailed'));return}const blob=new Blob([JSON.stringify(await response.json(),null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`wejdan-task-${taskId}.json`;a.click();URL.revokeObjectURL(url)}
async function deleteTask(taskId){if(!window.confirm(tr('confirmDeleteTask')))return;const response=await fetch(`http://127.0.0.1:8766/api/tasks/${encodeURIComponent(taskId)}`,{method:'DELETE'});if(!response.ok){announce(tr('taskActionFailed'));return}closeDialog();await loadData();announce(tr('taskDeleted'))}
COPY.ar.noPersonalData='الجسر المحلي يشارك نص المهمة فقط بعد الموافقة.';COPY.en.noPersonalData='The local bridge shares only the approved task text.';
function syncNav(){const target=location.hash||'#overview';const current=$(`.nav-link[href="${target}"]`)||$('.nav-link[href="#overview"]');$$('.nav-link').forEach(link=>{const selected=link===current;link.classList.toggle('selected',selected);if(selected)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current')});if(current&&matchMedia('(max-width: 780px)').matches)current.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'})}
document.addEventListener('DOMContentLoaded',()=>{loadData().catch(err=>{console.error(err);announce(UI.lang==='ar'?'تعذر الاتصال بالخدمات المحلية. شغّلي n8n وAPI المحلي.':'Could not reach local services. Start n8n and the local API.')});$('#task-form').addEventListener('submit',submitTask);$('#plan-project').addEventListener('click',proposeProjectPlan);$('#approve-project').addEventListener('click',approveProjectPlan);$('#run-project').addEventListener('click',runProjectPlan);$('#project-name').addEventListener('input',()=>{});$('#project-goal').addEventListener('input',()=>{});$('#lang-toggle').addEventListener('click',()=>setLanguage(UI.lang==='ar'?'en':'ar'));$('#task-search').addEventListener('input',renderTasks);$('#status-filter').addEventListener('change',renderTasks);$('#role-search').addEventListener('input',renderRoles);$('#team-filter').addEventListener('change',renderRoles);$('#role-status-filter').addEventListener('change',renderRoles);$('#refresh-data').addEventListener('click',()=>loadData().catch(()=>announce(tr('apiUnavailable'))));$('#export-report').addEventListener('click',exportSummary);$('#dialog-close').addEventListener('click',closeDialog);$('#task-dialog').addEventListener('click',e=>{if(e.target===$('#task-dialog'))closeDialog()});$('#task-dialog').addEventListener('cancel',()=>{UI.restoreFocus?.focus()});$('.nav-list').addEventListener('click',()=>requestAnimationFrame(syncNav));window.addEventListener('hashchange',syncNav);syncNav();setLanguage('ar')});
